import React, { useState, useRef, useEffect } from 'react';
import { Link } from 'react-router-dom';
import './History.css';

/* ═══════════════════════════════════════════════════════════
   SEASON DATA
═══════════════════════════════════════════════════════════ */
const SEASONS = [
  {
    id:    'decode',
    year:  '2025',
    game:  'Decode',
    robot: 'Pegasus',
    tag:   'completed',
    label: 'Decode 2025',
    type:  'completed',
    league: 'East Bay League',
    location: 'Dublin, CA',
    division: 'FTC',
    intro:
      'Our rookie season with Pegasus — a precision-built robot powered by OnShape CAD ' +
      'and a Java + Pedro Pathing software stack. Pegasus competed in four East Bay League ' +
      'events, earned a Connect Award at the League Tournament, and set the foundation ' +
      'for everything Team 30473 will build next.',
    stats: [
      { val: '4',      label: 'Events Competed' },
      { val: '20',     label: 'Matches Played'  },
      { val: 'Top 10', label: 'Tournament Rank' },
      { val: '1',      label: 'Award Won'        },
    ],
    award: {
      icon:  '🏆',
      name:  'Connect Award',
      event: 'East Bay League Tournament',
      desc:
        'The FIRST Tech Challenge Connect Award recognizes teams that best exemplify the ' +
        'FIRST mission — inspiring others to pursue STEM through advocacy, partnerships, and ' +
        'outreach. Winning this in our rookie season reflects our commitment to community ' +
        'impact, from founding BASE Robotics to hosting free workshops across the Tri-Valley.',
      outreachStats: [
        { val: '2',    label: 'Nonprofits Founded / Joined' },
        { val: '100+', label: 'Students Reached' },
        { val: '4',    label: 'FTC Teams Assisted' },
      ],
    },
    events: [
      {
        id:        'meet-1',
        name:      'East Bay League — Meet 1',
        shortName: 'Meet 1',
        date:      'Oct 2024',
        venue:     'East Bay Region, CA',
        result:    'Participated',
        status:    'debut',
        isAward:   false,
        detail:
          'Pegasus took the competition field for the very first time. We stress-tested our ' +
          'autonomous routines in a live match environment, validating Pedro Pathing trajectory ' +
          'accuracy and gathering critical performance data to drive our next round of ' +
          'mechanical and software refinements.',
      },
      {
        id:        'meet-2',
        name:      'East Bay League — Meet 2',
        shortName: 'Meet 2',
        date:      'Nov 2024',
        venue:     'East Bay Region, CA',
        result:    'Participated',
        status:    'competed',
        isAward:   false,
        detail:
          'Armed with Match 1 footage and telemetry data, Pegasus returned with targeted ' +
          'hardware updates and refined Pedro Pathing trajectories — improving our autonomous ' +
          'cycle count and tightening driver-to-robot coordination in teleop.',
      },
      {
        id:        'meet-3',
        name:      'East Bay League — Meet 3',
        shortName: 'Meet 3',
        date:      'Dec 2024',
        venue:     'East Bay Region, CA',
        result:    'Participated',
        status:    'competed',
        isAward:   false,
        detail:
          'Our most polished regular-season outing. Pegasus\'s autonomous reliability reached ' +
          'a new high-water mark, with Pinpoint odometry holding sub-2 cm positional accuracy ' +
          'across full-field traversals. Alliance coordination showed measurable improvement ' +
          'heading into the League Tournament.',
      },
      {
        id:        'tournament',
        name:      'East Bay League Tournament',
        shortName: 'Tournament',
        date:      'Jan 2025',
        venue:     'East Bay Region, CA',
        result:    '🏆 Connect Award',
        status:    'award',
        isAward:   true,
        detail:
          'Pegasus delivered its defining performance — 20 successful matches across 4 ' +
          'competitions, driven by Pinpoint odometry and Pedro Pathing for reliable, ' +
          'repeatable autonomous cycles. We were selected as the 1st pick of the 3rd Alliance, ' +
          'contributed consistent teleop scoring through the playoff bracket, and finished ' +
          '4th place overall. The event concluded with Team 30473 taking home the ' +
          'FIRST Tech Challenge Connect Award.',
      },
    ],
  },
  {
    id:    'biobuzz',
    year:  '2026',
    game:  'BIOBUZZ',
    robot: 'TBD',
    tag:   'upcoming',
    label: 'BIOBUZZ 2026',
    type:  'upcoming',
    league: 'East Bay League',
    location: 'Dublin, CA',
    division: 'FTC',
    intro:
      'Our second season. Hardware development is underway and our Pedro Pathing software ' +
      'stack is being refined based on lessons learned with Pegasus. The team is targeting ' +
      'a stronger mechanical package and more aggressive autonomous strategy for BIOBUZZ.',
    stats: [
      { val: '4', label: 'Events Scheduled' },
      { val: '—', label: 'Matches Played'   },
      { val: '—', label: 'Current Rank'     },
      { val: '—', label: 'Awards'           },
    ],
    events: [
      {
        id:        'biobuzz-meet-1',
        name:      'East Bay League — Meet 1',
        shortName: 'Meet 1',
        date:      'Fall 2025',
        venue:     'East Bay Region, CA',
        result:    'TBD',
        status:    'upcoming',
        isAward:   false,
        detail:
          'Our first official match of the BIOBUZZ season. Hardware and software development ' +
          'is underway as we adapt our platform to the new game challenge.',
      },
      {
        id:        'biobuzz-meet-2',
        name:      'East Bay League — Meet 2',
        shortName: 'Meet 2',
        date:      'Winter 2025',
        venue:     'East Bay Region, CA',
        result:    'TBD',
        status:    'upcoming',
        isAward:   false,
        detail:
          'Building on Meet 1 field data, we plan to deploy fully refined autonomous routines ' +
          'and a competition-hardened scoring mechanism.',
      },
      {
        id:        'biobuzz-meet-3',
        name:      'East Bay League — Meet 3',
        shortName: 'Meet 3',
        date:      'Winter 2025',
        venue:     'East Bay Region, CA',
        result:    'TBD',
        status:    'upcoming',
        isAward:   false,
        detail:
          'Our most polished regular-season outing of the BIOBUZZ campaign. Three meets of ' +
          'field data will allow us to push Pedro Pathing trajectory accuracy and teleop ' +
          'execution to their limits ahead of the League Tournament.',
      },
      {
        id:        'biobuzz-tournament',
        name:      'East Bay League Tournament',
        shortName: 'Tournament',
        date:      'Early 2026',
        venue:     'East Bay Region, CA',
        result:    'TBD',
        status:    'upcoming',
        isAward:   false,
        detail:
          'Our second League Tournament — and our first opportunity to defend the standard ' +
          'we set in our rookie year. Goals include a stronger alliance pick and deeper ' +
          'playoff run than the Decode season.',
      },
    ],
  },
];

/* ═══════════════════════════════════════════════════════════
   SEASON DROPDOWN
═══════════════════════════════════════════════════════════ */
function SeasonDropdown({ seasons, selected, onSelect }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);

  useEffect(() => {
    const close = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener('mousedown', close);
    return () => document.removeEventListener('mousedown', close);
  }, []);

  useEffect(() => {
    const esc = (e) => { if (e.key === 'Escape') setOpen(false); };
    document.addEventListener('keydown', esc);
    return () => document.removeEventListener('keydown', esc);
  }, []);

  const active = seasons.find((s) => s.id === selected);

  return (
    <div
      className={`hx-dropdown${open ? ' hx-dropdown--open' : ''}`}
      ref={ref}
      aria-label="Season selector"
    >
      <button
        id="season-dropdown-trigger"
        className="hx-dropdown__trigger"
        onClick={() => setOpen((o) => !o)}
        aria-haspopup="listbox"
        aria-expanded={open}
      >
        <span className="hx-dropdown__trigger-inner">
          <span className="hx-dropdown__eyebrow">Season</span>
          <span className="hx-dropdown__current">{active?.label}</span>
        </span>
        <span className="hx-dropdown__arrow" aria-hidden="true">
          <svg width="10" height="6" viewBox="0 0 10 6" fill="none">
            <path d="M1 1L5 5L9 1" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
          </svg>
        </span>
      </button>

      <ul className="hx-dropdown__menu" role="listbox" aria-label="Available seasons">
        {seasons.map((s) => (
          <li
            key={s.id}
            id={`season-opt-${s.id}`}
            role="option"
            aria-selected={s.id === selected}
            className={`hx-dropdown__option${s.id === selected ? ' hx-dropdown__option--active' : ''}`}
            onClick={() => { onSelect(s.id); setOpen(false); }}
          >
            <span className="hx-dropdown__opt-label">{s.label}</span>
            <span className={`hx-dropdown__opt-tag hx-tag--${s.tag}`}>
              {s.tag === 'completed' ? 'Completed' : 'Upcoming'}
            </span>
            {s.id === selected && (
              <svg className="hx-dropdown__check" width="12" height="12" viewBox="0 0 12 12" fill="none" aria-hidden="true">
                <path d="M2 6L5 9L10 3" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"/>
              </svg>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════
   STATS STRIP
═══════════════════════════════════════════════════════════ */
function StatsStrip({ stats }) {
  return (
    <div className="hx-stats-strip" aria-label="Season statistics">
      {stats.map(({ val, label }) => (
        <div key={label} className="hx-stats-strip__cell">
          <span className="hx-stats-strip__val">{val}</span>
          <span className="hx-stats-strip__label">{label}</span>
        </div>
      ))}
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════
   HORIZONTAL EVENT CARD
═══════════════════════════════════════════════════════════ */
const STATUS_CONFIG = {
  debut:    { label: 'Debut',     className: 'hx-tag--debut'    },
  competed: { label: 'Competed',  className: 'hx-tag--competed' },
  award:    { label: '🏆 Award',  className: 'hx-tag--award'    },
  upcoming: { label: 'Upcoming',  className: 'hx-tag--upcoming' },
};

function EventCard({ event, robot, index }) {
  const cfg = STATUS_CONFIG[event.status] ?? STATUS_CONFIG.competed;

  /* Highlight robot name in yellow on first occurrence */
  const renderDetail = () => {
    if (!robot || robot === 'TBD') return event.detail;
    const idx = event.detail.indexOf(robot);
    if (idx === -1) return event.detail;
    return (
      <>
        {event.detail.slice(0, idx)}
        <strong className="hx-robot-name">{robot}</strong>
        {event.detail.slice(idx + robot.length)}
      </>
    );
  };

  return (
    <article
      id={event.id}
      className={`hx-event-card${event.isAward ? ' hx-event-card--award' : ''} animate-fadeInUp delay-${(index % 4) + 1}`}
      aria-label={event.name}
    >
      {/* ── Left: index number ── */}
      <div className="hx-event-card__index" aria-hidden="true">
        {String(index + 1).padStart(2, '0')}
      </div>

      {/* ── Center: main content ── */}
      <div className="hx-event-card__body">
        <div className="hx-event-card__header">
          <div className="hx-event-card__title-group">
            <h3 className="hx-event-card__name">{event.name}</h3>
            <span className="hx-event-card__meta">
              <span className="hx-event-card__date">{event.date}</span>
              <span className="hx-event-card__sep" aria-hidden="true">·</span>
              <span className="hx-event-card__venue">{event.venue}</span>
            </span>
          </div>
          <span className={`hx-tag ${cfg.className}`}>{cfg.label}</span>
        </div>

        <p className="hx-event-card__detail">{renderDetail()}</p>
      </div>

      {/* ── Right: result chip ── */}
      <div className="hx-event-card__result-col">
        {event.status !== 'upcoming' ? (
          <span className={`hx-event-card__result${event.isAward ? ' hx-event-card__result--award' : ''}`}>
            {event.result}
          </span>
        ) : (
          <span className="hx-event-card__result hx-event-card__result--pending">
            Pending
          </span>
        )}
      </div>
    </article>
  );
}

/* ═══════════════════════════════════════════════════════════
   CONNECT AWARD BLOCK
═══════════════════════════════════════════════════════════ */
function ConnectAwardBlock({ award, game }) {
  return (
    <div className="hx-award-block" id="connect-award" aria-label="Award detail section">
      {/* Glow layer */}
      <div className="hx-award-block__glow" aria-hidden="true" />

      <div className="hx-award-block__content">
        {/* Header */}
        <div className="hx-award-block__header">
          <span className="hx-award-block__trophy" aria-hidden="true">{award.icon}</span>
          <div>
            <p className="hx-eyebrow">Highest Achievement · {game} Season</p>
            <h3 className="hx-award-block__title">
              {award.name} <span className="hx-yellow">&mdash; Winner</span>
            </h3>
          </div>
        </div>

        {/* Description */}
        <p className="hx-award-block__desc">{award.desc}</p>

        {/* Outreach stats row */}
        <div className="hx-award-block__stats">
          {award.outreachStats.map(({ val, label }) => (
            <div key={label} className="hx-award-block__stat">
              <span className="hx-award-block__stat-val">{val}</span>
              <span className="hx-award-block__stat-label">{label}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════
   TOURNAMENT MONTAGE
═══════════════════════════════════════════════════════════ */
const TOURNAMENT_STATS = [
  { label: 'Matches Played',  value: '20'                    },
  { label: 'Events',          value: '4 competitions'        },
  { label: 'Alliance Pick',   value: '1st Pick · 3rd Seed'  },
  { label: 'Final Standing',  value: '4th Place Alliance'    },
  { label: 'Award',           value: 'Connect Award'         },
];

function TournamentMontage() {
  return (
    <section className="hx-montage" id="tournament-montage" aria-label="Tournament montage">
      <div className="hx-montage__header">
        <span className="hx-eyebrow">Pegasus · East Bay League Tournament · Jan 2025</span>
        <h3 className="hx-montage__title">
          Tournament <span className="hx-yellow">Montage</span>
        </h3>
        <p className="hx-montage__sub">
          Full match footage, autonomous runs, and playoff moments from the East Bay League Tournament.
          Video is currently in post-production.
        </p>
      </div>

      <div className="hx-montage__grid">
        {/* Player */}
        <div className="hx-montage__player" aria-label="Tournament montage video">
          <iframe
            id="montage-iframe"
            className="hx-montage__iframe"
            src="https://www.youtube.com/embed/dQw4w9WgXcQ"
            title="Team Duck 30473 — East Bay League Tournament Montage"
            frameBorder="0"
            allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
            allowFullScreen
          />
          <div className="hx-montage__badge">
            <span className="hx-montage__badge-dot" aria-hidden="true" />
            Editing in Progress
          </div>
        </div>

        {/* Stats sidebar */}
        <aside className="hx-montage__sidebar" aria-label="Pegasus tournament statistics">
          <p className="hx-eyebrow hx-montage__sidebar-label">Pegasus · Season Stats</p>
          <div className="hx-montage__stat-list">
            {TOURNAMENT_STATS.map(({ label, value }) => (
              <div key={label} className="hx-montage__stat-row">
                <span className="hx-montage__stat-label">{label}</span>
                <span className="hx-montage__stat-value">{value}</span>
              </div>
            ))}
          </div>
        </aside>
      </div>
    </section>
  );
}

/* ═══════════════════════════════════════════════════════════
   UPCOMING BANNER
═══════════════════════════════════════════════════════════ */
function UpcomingBanner() {
  return (
    <div className="hx-upcoming-banner">
      <span className="hx-upcoming-banner__dot" aria-hidden="true" />
      <p className="hx-upcoming-banner__text">
        This season is currently in preparation. Results and performance recaps will appear
        here after each event concludes.
      </p>
      <Link to="/" className="btn btn-outline hx-btn-sm" id="history-home-cta">
        ← Back to Home
      </Link>
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════
   PAGE EXPORT
═══════════════════════════════════════════════════════════ */
export default function History() {
  const [selectedId, setSelectedId] = useState('decode');
  const season = SEASONS.find((s) => s.id === selectedId);

  return (
    <main className="page" id="history-page">

      {/* ══ PAGE HERO ══ */}
      <section className="hx-hero" aria-labelledby="hx-hero-heading">
        <div className="hx-hero__bg"   aria-hidden="true" />
        <div className="hx-hero__grid" aria-hidden="true" />

        <div className="container hx-hero__inner">
          <span className="hx-eyebrow">30473 · Season Record</span>
          <h1 id="hx-hero-heading" className="hx-hero__title">
            Competition <span className="hx-yellow">History</span>
          </h1>
          <p className="hx-hero__sub">
            Every match. Every award. Every lesson carried forward.
            This is how <span className="hx-yellow">Pegasus</span> and Team 30473 compete.
          </p>

          {/* Career quick stats */}
          <div className="hx-hero__qs">
            <div className="hx-hero__qs-cell">
              <span className="hx-hero__qs-val">1</span>
              <span className="hx-hero__qs-key">Award Won</span>
            </div>
            <div className="hx-hero__qs-divider" aria-hidden="true" />
            <div className="hx-hero__qs-cell">
              <span className="hx-hero__qs-val">4</span>
              <span className="hx-hero__qs-key">Meets Competed</span>
            </div>
            <div className="hx-hero__qs-divider" aria-hidden="true" />
            <div className="hx-hero__qs-cell">
              <span className="hx-hero__qs-val">2025</span>
              <span className="hx-hero__qs-key">Rookie Year</span>
            </div>
            <div className="hx-hero__qs-divider" aria-hidden="true" />
            <div className="hx-hero__qs-cell">
              <span className="hx-hero__qs-val hx-yellow">Decode</span>
              <span className="hx-hero__qs-key">Current Season</span>
            </div>
          </div>
        </div>
      </section>

      {/* ══ DASHBOARD ══ */}
      <section className="hx-dashboard section" aria-label="Season dashboard">
        <div className="container">

          {/* ─ Control Bar ─ */}
          <div className="hx-ctrl-bar">

            {/* Season Dropdown */}
            <SeasonDropdown
              seasons={SEASONS}
              selected={selectedId}
              onSelect={setSelectedId}
            />

            {/* Season identity */}
            <div className="hx-ctrl-bar__identity">
              <div className="hx-ctrl-bar__title-row">
                <h2 className="hx-ctrl-bar__title">
                  {season.game}{' '}
                  <span className="hx-yellow">{season.year}</span>
                </h2>
                <div className="hx-ctrl-bar__pills">
                  <span className={`hx-tag hx-tag--${season.tag}`}>
                    {season.tag === 'completed' ? 'Season Complete' : 'Upcoming Season'}
                  </span>
                  {season.robot !== 'TBD' && (
                    <span className="hx-robot-pill">
                      🤖 <span className="hx-yellow">{season.robot}</span>
                    </span>
                  )}
                </div>
              </div>
              <p className="hx-ctrl-bar__sub">
                {season.league} &nbsp;·&nbsp; {season.location} &nbsp;·&nbsp; {season.division}
              </p>
              <p className="hx-ctrl-bar__intro">{season.intro}</p>
            </div>
          </div>

          {/* ─ Stats Strip ─ */}
          <StatsStrip stats={season.stats} />

          {/* ─ Panel ─ */}
          <div className="hx-panel" key={selectedId}>

            {season.type === 'upcoming' && <UpcomingBanner />}

            {/* Montage — decode season only */}
            {season.id === 'decode' && <TournamentMontage />}

            {/* Award banner pill */}
            {season.award && (
              <div className="hx-award-pill" aria-label="Season award">
                <span className="hx-award-pill__icon" aria-hidden="true">{season.award.icon}</span>
                <span className="hx-award-pill__name">{season.award.name}</span>
                <span className="hx-award-pill__event">{season.award.event}</span>
              </div>
            )}

            {/* ─ Event Feed ─ */}
            <div className="hx-event-feed" role="list" aria-label={`${season.game} events`}>
              <div className="hx-event-feed__header">
                <span className="hx-eyebrow">Event Feed</span>
                <span className="hx-event-feed__count">{season.events.length} events</span>
              </div>

              <div className="hx-event-feed__list">
                {season.events.map((event, i) => (
                  <EventCard
                    key={event.id}
                    event={event}
                    robot={season.robot}
                    index={i}
                  />
                ))}
              </div>
            </div>

            {/* Connect Award Feature Block */}
            {season.award && (
              <ConnectAwardBlock award={season.award} game={season.game} />
            )}

          </div>
        </div>
      </section>

    </main>
  );
}
